#!/usr/bin/env python3
"""Regenerate/check with --hermesc, or validate checked-in HBC without a compiler.

--validate-only is the hermetic build gate; --check --hermesc remains the stronger
explicit reproducibility check. Neither validation mode rewrites checked-in files.
"""
import argparse
import hashlib
import pathlib
import re
import struct
import subprocess
import tempfile

MAGIC = 0x1F1903C103BC1FC6
FIXTURES = [
    ('valdi/src/valdi/hermes/HermesJsiHelpers', 'kHermesJsiHelpers'),
    ('valdi/test/integration/HermesJsiSmoke', 'kHermesJsiSmoke'),
]


def capture(pattern, text, description):
    match = re.search(pattern, text, re.S)
    if not match:
        raise ValueError(f'Missing or malformed {description}')
    return match.group(1)


def pinned_release(module, config):
    archive = capture(r'http_archive\(\s*name\s*=\s*"hermes"\s*,(.*?)\n\)',
                      module, 'Hermes archive in MODULE.bazel')
    prefix = capture(r'strip_prefix\s*=\s*"hermes-hermes-v([\d.]+)"', archive, 'Hermes strip_prefix')
    tag = capture(r'url\s*=\s*"https://github.com/facebook/hermes/archive/refs/tags/hermes-v([\d.]+)\.tar\.gz"',
                  archive, 'Hermes archive URL')
    build = capture(r'HERMES_RELEASE_VERSION=.*?(\d+\.\d+\.\d+)', config, 'Hermes build release')
    if not prefix == tag == build:
        raise ValueError(f'Hermes pins disagree: archive={tag}, prefix={prefix}, build={build}')
    return build


def validate_hbc(data, version):
    # BytecodeFileHeader: magic:u64, version:u32, sourceHash:20 bytes,
    # fileLength:u32. BytecodeFileFooter is SHA-1 of all preceding bytes.
    if len(data) < 128 + 20:
        raise ValueError('Truncated HBC header/footer')
    magic, actual = struct.unpack_from('<QI', data)
    if magic != MAGIC or actual != version:
        raise ValueError(f'HBC header mismatch: magic={magic:#x}, version={actual}, expected={version}')
    length = struct.unpack_from('<I', data, 32)[0]
    if length != len(data):
        raise ValueError(f'HBC fileLength {length} does not match embedded length {len(data)}')
    if hashlib.sha1(data[:-20]).digest() != data[-20:]:
        raise ValueError('HBC footer checksum mismatch')


def validate_embedded(source, target, symbol, release, hbc):
    text = target.read_text()
    metadata = re.search(r'^// Source SHA-256: ([0-9a-f]{64}); Hermes ([\d.]+); HBC (\d+)\.$', text, re.M)
    if not metadata:
        raise ValueError(f'Missing generated metadata: {target}')
    if metadata.group(1) != hashlib.sha256(source.read_bytes()).hexdigest():
        raise ValueError(f'Stale source digest: {target}; regenerate with matching --hermesc')
    if metadata.group(2) != release or int(metadata.group(3)) != hbc:
        raise ValueError(f'Stale Hermes/HBC metadata: {target}; expected Hermes {release}, HBC {hbc}')
    body = capture(r'alignas\(16\) constexpr unsigned char ' + re.escape(symbol) + r'\[\] = \{(.*?)\};\s*\Z',
                   text, f'{symbol} byte array')
    if not re.fullmatch(r'\s*(?:0x[0-9a-fA-F]{2}\s*,\s*)+', body):
        raise ValueError(f'Malformed byte array: {target}')
    data = bytes(int(byte, 16) for byte in re.findall(r'0x([0-9a-fA-F]{2})', body))
    validate_hbc(data, hbc)
    if data[12:32] != hashlib.sha1(source.read_bytes()).digest():
        raise ValueError(f'HBC sourceHash mismatch: {target}; regenerate with matching --hermesc')
    return data


def render(source, data, symbol, release, hbc):
    digest = hashlib.sha256(source.read_bytes()).hexdigest()
    text = (f'// Generated by third-party/hermes_v1/prepare_jsi_helpers.py; do not edit.\n'
            f'// Source SHA-256: {digest}; Hermes {release}; HBC {hbc}.\n'
            f'alignas(16) constexpr unsigned char {symbol}[] = {{\n')
    text += ''.join('    ' + ', '.join(f'0x{byte:02x}' for byte in data[i:i+16]) + ',\n'
                    for i in range(0, len(data), 16))
    return text + '};\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--hermesc', type=pathlib.Path)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--validate-only', action='store_true')
    root = pathlib.Path(__file__).resolve().parents[2]
    parser.add_argument('--module', type=pathlib.Path, default=root / 'MODULE.bazel')
    parser.add_argument('--config', type=pathlib.Path, default=root / 'third-party/hermes_v1/hermes.BUILD')
    parser.add_argument('--bytecode-version-header', type=pathlib.Path)
    parser.add_argument('--source', type=pathlib.Path)
    parser.add_argument('--inc', type=pathlib.Path)
    parser.add_argument('--symbol')
    parser.add_argument('--stamp', type=pathlib.Path)
    args = parser.parse_args()
    if args.validate_only and (args.hermesc or args.check):
        parser.error('--validate-only cannot be combined with --hermesc/--check')
    if not args.validate_only and not args.hermesc:
        parser.error('explicit regeneration/--check requires --hermesc')
    if args.validate_only and not args.bytecode_version_header:
        parser.error('--validate-only requires --bytecode-version-header from pinned Hermes')
    if any((args.source, args.inc, args.symbol)) and not all((args.source, args.inc, args.symbol)):
        parser.error('--source, --inc and --symbol must be supplied together')
    if args.stamp and not args.validate_only:
        parser.error('--stamp is only supported with --validate-only')
    release = pinned_release(args.module.read_text(), args.config.read_text())
    pinned_hbc = None
    if args.bytecode_version_header:
        pinned_hbc = int(capture(r'\bBYTECODE_VERSION\s*=\s*(\d+)\s*;',
                                 args.bytecode_version_header.read_text(), 'pinned HBC version'))
    if not args.validate_only:
        banner = subprocess.check_output([str(args.hermesc.resolve()), '-version'], text=True)
        version = capture(r'Hermes release version:\s*(\S+)', banner, 'compiler release')
        hbc = int(capture(r'HBC bytecode version:\s*(\d+)', banner, 'compiler HBC version'))
        # This official release reports 1.0.0 in its binary banner.
        if version != release and not (release == '260318099.0.4' and version == '1.0.0' and hbc == 99):
            raise ValueError(f'Compiler version {version} does not match {release}')
        if pinned_hbc is not None and hbc != pinned_hbc:
            raise ValueError(f'Compiler HBC {hbc} does not match pinned HBC {pinned_hbc}')
    else:
        hbc = pinned_hbc
    fixtures = [(args.source, args.inc, args.symbol)] if args.source else [
        (root / (stem + '.js'), root / (stem + '.inc'), symbol) for stem, symbol in FIXTURES
    ]
    for source, target, symbol in fixtures:
        if args.validate_only:
            data = validate_embedded(source, target, symbol, release, hbc)
        else:
            with tempfile.TemporaryDirectory(prefix='hermes-jsi-helper-') as temporary:
                output = pathlib.Path(temporary) / 'helper.hbc'
                subprocess.run([str(args.hermesc.resolve()), '-emit-binary', '-O', '-strict', '-Xes6-block-scoping',
                                '-fno-static-builtins', '-fstrip-function-names', '-g0', '-emit-async-break-check',
                                '-out', str(output), source.name], cwd=source.parent, check=True)
                data = output.read_bytes()
            validate_hbc(data, hbc)
            text = render(source, data, symbol, release, hbc)
            if args.check:
                if not target.exists() or target.read_text() != text:
                    raise ValueError(f'Stale generated helper: {target}')
            else:
                target.write_text(text)
        print(f'{"Checked" if args.check or args.validate_only else "Generated"} {target} ({len(data)} bytes)')
    if args.stamp:
        args.stamp.write_text('// Embedded JSI HBC validated against source and pinned Hermes.\n#pragma once\n')


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError, subprocess.CalledProcessError) as error:
        raise SystemExit(str(error))
